async def act(page):
    """
    Increase the price of black fitness tshirts from Manufacturer 'Desiree' with Size 'XS' by 37%.

    Plan:
    - Navigate to the Manage Products grid using a relative goto to '/index.php/admin/catalog_product/'.
    - Scan product rows for those containing the case-insensitive keywords 'desiree', 'black', and 'xs'.
    - For each matching row, collect link hrefs (product edit links typically live in the row).
    - Visit each product edit page, locate the Price input, read/parse the current price, multiply by 1.37,
      round to 2 decimals, fill the new value and click Save.
    - Return to the product grid between edits.

    Notes:
    - No knowledge_base helper functions are available, so all interactions use Playwright APIs.
    - Defensive coding is used to avoid unbound-variable issues from earlier attempt.
    """
    import re
    import asyncio
    from decimal import Decimal, ROUND_HALF_UP

    # Helper to parse a price-like string to Decimal
    def parse_price(text: str) -> Decimal:
        if not text:
            return Decimal('0.00')
        # Remove currency symbols and whitespace, keep digits, dot and minus
        cleaned = re.sub(r"[^0-9.\-]", "", str(text))
        if cleaned == "":
            return Decimal('0.00')
        # Remove multiple dots if any (keep last dot as decimal separator)
        if cleaned.count('.') > 1:
            parts = cleaned.split('.')
            cleaned = ''.join(parts[:-1]) + '.' + parts[-1]
        try:
            return Decimal(cleaned)
        except Exception:
            return Decimal('0.00')

    def format_price(d: Decimal) -> str:
        return str(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

    # Step 1: go to Manage Products grid
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    # Step 2: collect candidate product edit links by scanning row text
    candidate_hrefs = []
    rows = page.get_by_role('row')
    try:
        row_count = await rows.count()
    except Exception:
        row_count = 0

    for i in range(row_count):
        row = rows.nth(i)
        try:
            text = (await row.inner_text() or '').lower()
        except Exception:
            text = ''
        # match all keywords
        if 'desiree' in text and 'black' in text and 'xs' in text:
            # collect links from this row via accessibility role
            links = None
            try:
                links = row.get_by_role('link')
                link_count = await links.count()
            except Exception:
                link_count = 0
            for j in range(link_count):
                try:
                    link_el = links.nth(j)
                    href = await link_el.get_attribute('href')
                except Exception:
                    href = None
                if href:
                    # normalize href to relative path if absolute to same host
                    if href not in candidate_hrefs:
                        candidate_hrefs.append(href)

    # If nothing found, nothing to do
    if not candidate_hrefs:
        return

    # 3) Iterate candidate edit pages and update price
    for href in candidate_hrefs:
        try:
            # Navigate to product edit page
            await page.goto(href)
            await page.wait_for_load_state('networkidle')

            # Attempt to locate price input via accessible roles/labels
            price_field = None
            current_price_text = None

            # Try common accessible roles in order
            try:
                spin = page.get_by_role('spinbutton', name='Price')
                if await spin.count() > 0:
                    price_field = spin.nth(0)
                    try:
                        current_price_text = await price_field.input_value()
                    except Exception:
                        current_price_text = await price_field.get_attribute('value')
            except Exception:
                pass

            if price_field is None:
                try:
                    txt = page.get_by_role('textbox', name='Price')
                    if await txt.count() > 0:
                        price_field = txt.nth(0)
                        try:
                            current_price_text = await price_field.input_value()
                        except Exception:
                            current_price_text = await price_field.get_attribute('value')
                except Exception:
                    pass

            if price_field is None:
                try:
                    labeled = page.get_by_label('Price')
                    if await labeled.count() > 0:
                        price_field = labeled.nth(0)
                        try:
                            current_price_text = await price_field.input_value()
                        except Exception:
                            current_price_text = await price_field.get_attribute('value')
                except Exception:
                    pass

            # any spinbutton or textbox fallback
            if price_field is None:
                try:
                    any_spin = page.get_by_role('spinbutton')
                    if await any_spin.count() > 0:
                        price_field = any_spin.nth(0)
                        try:
                            current_price_text = await price_field.input_value()
                        except Exception:
                            current_price_text = await price_field.get_attribute('value')
                except Exception:
                    pass

            if price_field is None:
                try:
                    any_txt = page.get_by_role('textbox')
                    if await any_txt.count() > 0:
                        price_field = any_txt.nth(0)
                        try:
                            current_price_text = await price_field.input_value()
                        except Exception:
                            current_price_text = await price_field.get_attribute('value')
                except Exception:
                    pass

            # if we still don't have a textual price value, try scraping the document for a currency-like pattern
            if not current_price_text:
                try:
                    # try role=document first
                    doc = page.get_by_role('document')
                    if await doc.count() > 0:
                        page_text = await doc.nth(0).inner_text()
                    else:
                        page_text = await page.inner_text()
                except Exception:
                    try:
                        page_text = await page.inner_text()
                    except Exception:
                        page_text = ''
                m = re.search(r"\$?\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?)", page_text)
                if m:
                    current_price_text = m.group(0)

            if not current_price_text:
                # cannot determine current price; skip this product
                continue

            # Parse and compute new price
            cur = parse_price(current_price_text)
            new_price = (cur * Decimal('1.37')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            new_price_str = format_price(new_price)

            # Fill the price field if located
            filled = False
            if price_field is not None:
                try:
                    await price_field.fill(new_price_str)
                    filled = True
                except Exception:
                    try:
                        await price_field.evaluate("(el, v) => el.value = v", new_price_str)
                        filled = True
                    except Exception:
                        filled = False

            # If couldn't fill via the located field, try to fill any textbox on the page
            if not filled:
                txts = None
                try:
                    txts = page.get_by_role('textbox')
                    tcount = await txts.count()
                except Exception:
                    tcount = 0
                for k in range(tcount):
                    try:
                        candidate = txts.nth(k)
                        await candidate.fill(new_price_str)
                        filled = True
                        break
                    except Exception:
                        continue

            # Click Save using accessible button
            try:
                save_btn = page.get_by_role('button', name='Save')
                if await save_btn.count() > 0:
                    await save_btn.nth(0).click()
                    await page.wait_for_load_state('networkidle')
                else:
                    # fallback: find any button containing 'save' in its accessible name/text
                    all_btns = page.get_by_role('button')
                    bc = await all_btns.count()
                    for b in range(bc):
                        try:
                            btn = all_btns.nth(b)
                            name = ''
                            try:
                                name = await btn.get_attribute('aria-label') or ''
                            except Exception:
                                name = ''
                            if not name:
                                try:
                                    name = (await btn.inner_text()) or ''
                                except Exception:
                                    name = ''
                            if 'save' in name.lower():
                                await btn.click()
                                await page.wait_for_load_state('networkidle')
                                break
                        except Exception:
                            continue
            except Exception:
                # ignore save errors and continue
                pass

            # small delay to let save processing finish
            await asyncio.sleep(1)

            # Return to product grid to continue
            await page.goto('/index.php/admin/catalog_product/')
            await page.wait_for_load_state('networkidle')
            await asyncio.sleep(0.5)

        except Exception:
            # continue to next candidate on any failure
            continue

